    if (keys.ArrowUp || keys.w) ship.y -= speed * dt;
    if (keys.ArrowDown || keys.s) ship.y += speed * dt;
    if (keys.ArrowLeft || keys.a) ship.x -= speed * dt;
    if (keys.ArrowRight || keys.d) ship.x += speed * dt;
